    public static void startServer(String bindIp, int port, String responseIp) throws IOException {
        DatagramSocket socket = new DatagramSocket(port, InetAddress.getByName(bindIp));
        byte[] buffer = new byte[512];

        while (true) {
            DatagramPacket request = new DatagramPacket(buffer, buffer.length);
            socket.receive(request);

            byte[] queryData = Arrays.copyOf(request.getData(), request.getLength());
            byte[] responseData = resolveDNS(queryData, responseIp);

            if (responseData.length > 0) {
                DatagramPacket response = new DatagramPacket(
                    responseData,
                    responseData.length,
                    request.getAddress(),
                    request.getPort()
                );
                socket.send(response);
            }
        }
    }

    public static byte[] resolveDNS(byte[] queryData, String responseIp) {
        try {
            DataInputStream dis = new DataInputStream(new ByteArrayInputStream(queryData));

            int transactionId = dis.readUnsignedShort();
            int flags = dis.readUnsignedShort();
            int qdcount = dis.readUnsignedShort();
            int ancount = dis.readUnsignedShort();
            int nscount = dis.readUnsignedShort();
            int arcount = dis.readUnsignedShort();

            StringBuilder domainName = new StringBuilder();
            int labelLength;
            while ((labelLength = dis.readUnsignedByte()) != 0) {
                byte[] label = new byte[labelLength];
                dis.readFully(label);
                if (domainName.length() > 0) domainName.append(".");
                domainName.append(new String(label));
            }

            int qtype = dis.readUnsignedShort();
            int qclass = dis.readUnsignedShort();

            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            DataOutputStream dos = new DataOutputStream(baos);

            dos.writeShort(transactionId);
            dos.writeShort(0x8180);
            dos.writeShort(1);
            dos.writeShort(1);
            dos.writeShort(0);
            dos.writeShort(0);

            writeDomainName(dos, domainName.toString());
            dos.writeShort(qtype);
            dos.writeShort(qclass);

            dos.writeShort(0xC00C);
            dos.writeShort(1);
            dos.writeShort(1);
            dos.writeInt(300);
            dos.writeShort(4);

            String[] parts = responseIp.split("\\.");
            for (String part : parts) {
                dos.writeByte(Integer.parseInt(part));
            }

            dos.flush();
            return baos.toByteArray();

        } catch (Exception e) {
            return new byte[0];
        }
    }

    private static void writeDomainName(DataOutputStream dos, String domain) throws IOException {
        if (domain.isEmpty()) {
            dos.writeByte(0);
            return;
        }
        String[] labels = domain.split("\\.");
        for (String label : labels) {
            dos.writeByte(label.length());
            dos.writeBytes(label);
        }
        dos.writeByte(0);
    }
